create extension if not exists pg_trgm;
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null default '' check(length(display_name)<=80), preferences jsonb not null default '{}', created_at timestamptz not null default now());
create function public.search_aliases(text[]) returns text language sql immutable as $$ select array_to_string($1,' ') $$;
create table public.anime (
 id bigint generated by default as identity primary key, title text not null, title_romaji text, title_native text, synonyms text[] not null default '{}', synopsis text, cover_url text, banner_url text,
 format text, year int, season text, airing_status text, episodes int check(episodes>0), duration int check(duration>0), genres text[] not null default '{}', studios text[] not null default '{}', popularity int,
 moderation text not null default 'quarantine' check(moderation in ('published','quarantine','excluded')), moderation_reason text not null, mature boolean not null default false,
 updated_at timestamptz not null default now(), search_text text generated always as (lower(title || ' ' || coalesce(title_romaji,'') || ' ' || coalesce(title_native,'') || ' ' || public.search_aliases(synonyms))) stored
);
create index anime_search on public.anime using gin(search_text gin_trgm_ops);
create index anime_published_popularity on public.anime(popularity desc nulls last,id) where moderation='published';
create index anime_genres on public.anime using gin(genres);
create table public.source_mappings (anime_id bigint not null references public.anime on delete cascade, provider text not null check(provider in ('anilist','mal','kitsu')), external_id text not null, url text not null, provenance text not null, confidence numeric not null check(confidence between 0 and 1), verified boolean not null default false, manual boolean not null default false, primary key(provider,external_id), unique(anime_id,provider));
create table public.ratings (anime_id bigint not null references public.anime on delete cascade, provider text not null, score numeric check(score>=0), scale numeric not null check(scale>0), votes bigint check(votes>=0), refreshed_at timestamptz not null default now(), primary key(anime_id,provider), check(score<=scale));
create table public.library (user_id uuid not null references auth.users on delete cascade, anime_id bigint not null references public.anime, status text not null default 'planned' check(status in ('planned','watching','completed','on_hold','dropped')), progress int not null default 0 check(progress>=0), score numeric check(score between 0 and 10), favorite boolean not null default false, priority int not null default 0 check(priority between 0 and 3), notes text not null default '' check(length(notes)<=10000), tags text[] not null default '{}', started_on date, completed_on date, rewatches int not null default 0 check(rewatches>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(user_id,anime_id));
create index library_user_status on public.library(user_id,status,updated_at desc);
create table public.viewing_events (id bigint generated always as identity primary key,user_id uuid not null references auth.users on delete cascade,anime_id bigint not null references public.anime,progress int not null,status text not null,created_at timestamptz not null default now());
create table public.collections (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,name text not null check(length(name) between 1 and 100),description text not null default '' check(length(description)<=1000),rules jsonb,pinned boolean not null default false,created_at timestamptz not null default now(),unique(id,user_id));
create table public.collection_members (collection_id uuid not null,user_id uuid not null,anime_id bigint not null,position int not null default 0,primary key(collection_id,anime_id),foreign key(collection_id,user_id) references public.collections(id,user_id) on delete cascade,foreign key(user_id,anime_id) references public.library(user_id,anime_id) on delete cascade);
create table public.entitlements (user_id uuid primary key references auth.users on delete cascade,ad_free boolean not null default false,stripe_customer text,stripe_session text unique,updated_at timestamptz not null default now());
create table public.webhook_events (id text primary key,created_at timestamptz not null default now());
create table public.purchases (session_id text primary key,user_id uuid references auth.users on delete set null,payment_intent text unique,status text not null,amount int not null check(amount=500),currency text not null check(currency='usd'),created_at timestamptz not null default now());
create table public.ingestion_jobs (provider text primary key,page int not null default 1,status text not null default 'pending',last_error text,updated_at timestamptz not null default now());
create table public.content_reports (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,anime_id bigint not null references public.anime,reason text not null check(length(reason) between 5 and 2000),created_at timestamptz not null default now());
create table public.admin_audit (id bigint generated always as identity primary key,actor text not null,action text not null,entity text not null,created_at timestamptz not null default now());
create function public.new_profile() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id) values(new.id); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_profile();
create function public.validate_library() returns trigger language plpgsql set search_path='' as $$ declare total int; begin select episodes into total from public.anime where id=new.anime_id; if total is not null and new.progress>total then raise exception 'Progress exceeds episode count'; end if; new.updated_at=now(); return new; end $$;
create trigger library_validate before insert or update on public.library for each row execute function public.validate_library();
create function public.log_progress() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.viewing_events(user_id,anime_id,progress,status) values(new.user_id,new.anime_id,new.progress,new.status); return new; end $$;
create trigger library_history after insert or update of progress,status on public.library for each row execute function public.log_progress();
-- Public catalog and every derived surface share this publication boundary.
alter table public.anime enable row level security;
create policy catalog_read on public.anime for select using(moderation='published');
alter table public.source_mappings enable row level security;
create policy mappings_read on public.source_mappings for select using(verified and exists(select 1 from public.anime a where a.id=anime_id and a.moderation='published'));
alter table public.ratings enable row level security;
create policy ratings_read on public.ratings for select using(exists(select 1 from public.anime a where a.id=anime_id and a.moderation='published'));
do $$ declare t text; begin foreach t in array array['profiles','library','viewing_events','collections','collection_members','entitlements','purchases','content_reports'] loop execute format('alter table public.%I enable row level security',t); if t='profiles' then execute format('create policy own_read on public.%I for select using(id=auth.uid())',t); execute format('create policy own_update on public.%I for update using(id=auth.uid()) with check(id=auth.uid())',t); else execute format('create policy own_read on public.%I for select using(user_id=auth.uid())',t); end if; end loop; end $$;
do $$ declare t text; begin foreach t in array array['library','collections','collection_members'] loop execute format('create policy own_write on public.%I for all using(user_id=auth.uid()) with check(user_id=auth.uid())',t); end loop; end $$;
create policy reports_insert on public.content_reports for insert with check(user_id=auth.uid());
alter table public.webhook_events enable row level security;
alter table public.ingestion_jobs enable row level security;
alter table public.admin_audit enable row level security;
-- Billing writes only through this atomic, service-role-only function.
create function public.apply_payment(event_id text, session_id text, account_id uuid, customer_id text, intent_id text, active boolean) returns void language plpgsql security definer set search_path='' as $$ begin
 insert into public.webhook_events(id) values(event_id) on conflict do nothing; if not found then return; end if;
 insert into public.purchases(session_id,user_id,payment_intent,status,amount,currency) values(session_id,case when exists(select 1 from auth.users where id=account_id) then account_id else null end,intent_id,case when active then 'paid' else 'revoked' end,500,'usd') on conflict on constraint purchases_pkey do update set status=excluded.status;
 if not exists(select 1 from auth.users where id=account_id) then return;end if;
 insert into public.entitlements(user_id,ad_free,stripe_customer,stripe_session) values(account_id,active,customer_id,session_id) on conflict(user_id) do update set ad_free=exists(select 1 from public.purchases p where p.user_id=account_id and p.status='paid'),stripe_customer=excluded.stripe_customer,stripe_session=excluded.stripe_session,updated_at=now();
end $$;
revoke all on function public.apply_payment(text,text,uuid,text,text,boolean) from public,anon,authenticated;
grant execute on function public.apply_payment(text,text,uuid,text,text,boolean) to service_role;
create table public.moderation_overrides(anime_id bigint primary key references public.anime,decision text not null check(decision in ('published','quarantine','excluded')),reason text not null,actor text not null,updated_at timestamptz not null default now());
alter table public.moderation_overrides enable row level security;
-- Run after each ingestion write as defense in depth. Manual exclusions always win.
create function public.enforce_override() returns trigger language plpgsql security definer set search_path='' as $$ declare d record; begin select * into d from public.moderation_overrides where anime_id=new.id; if found then new.moderation=d.decision;new.moderation_reason=d.reason;end if;return new;end $$;
create trigger enforce_moderation before update on public.anime for each row execute function public.enforce_override();
create function public.catalog_health() returns jsonb language sql security definer set search_path='' as $$ select jsonb_build_object(
 'published_eligible_distinct',(select count(distinct id) from public.anime where moderation='published'),
 'formats',(select coalesce(jsonb_object_agg(format,n),'{}') from (select coalesce(format,'unknown') format,count(*) n from public.anime where moderation='published' group by 1) x),
 'missing_images',(select count(*) from public.anime where moderation='published' and cover_url is null),
 'missing_synopsis',(select count(*) from public.anime where moderation='published' and synopsis is null),
 'mapping_coverage',(select count(distinct anime_id) from public.source_mappings where verified),
 'ratings_coverage',(select coalesce(jsonb_object_agg(provider,n),'{}') from (select provider,count(*) n from public.ratings where score is not null group by provider) x),
 'quarantined',(select count(*) from public.anime where moderation='quarantine'),
 'potential_duplicates',(select count(*) from (select lower(title),year,format from public.anime group by 1,2,3 having count(*)>1) x),
 'stale_records',(select count(*) from public.anime where updated_at<now()-interval '7 days')) $$;
revoke all on function public.catalog_health() from public,anon,authenticated;
grant execute on function public.catalog_health() to service_role;
create function public.correct_mapping(target_anime bigint,source_provider text,new_external text,operator_id text,explanation text) returns void language plpgsql security definer set search_path='' as $$ begin
 insert into public.source_mappings(anime_id,provider,external_id,url,provenance,confidence,verified,manual) values(target_anime,source_provider,new_external,case source_provider when 'anilist' then 'https://anilist.co/anime/' when 'mal' then 'https://myanimelist.net/anime/' when 'kitsu' then 'https://kitsu.app/anime/' end || new_external,explanation,1,true,true) on conflict(anime_id,provider) do update set external_id=excluded.external_id,url=excluded.url,provenance=excluded.provenance,confidence=1,verified=true,manual=true;
 delete from public.ratings where anime_id=target_anime and provider=source_provider;
 insert into public.admin_audit(actor,action,entity) values(operator_id,'mapping:' || source_provider || ':' || explanation,target_anime::text);
end $$;
revoke all on function public.correct_mapping(bigint,text,text,text,text) from public,anon,authenticated;
grant execute on function public.correct_mapping(bigint,text,text,text,text) to service_role;
create function public.personal_statistics() returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object(
 'total',(select count(*) from public.library where user_id=auth.uid()),
 'episodes',(select coalesce(sum(progress),0) from public.library where user_id=auth.uid()),
 'statuses',(select coalesce(jsonb_object_agg(status,n),'{}') from (select status,count(*) n from public.library where user_id=auth.uid() group by status) s),
 'scores',(select coalesce(jsonb_object_agg(score,n),'{}') from (select floor(score+0.5) score,count(*) n from public.library where user_id=auth.uid() and score is not null group by 1) s),
 'genres',(select coalesce(jsonb_object_agg(genre,n),'{}') from (select unnest(a.genres) genre,count(*) n from public.library l join public.anime a on a.id=l.anime_id where l.user_id=auth.uid() group by 1) s),
 'formats',(select coalesce(jsonb_object_agg(format,n),'{}') from (select coalesce(a.format,'Unknown') format,count(*) n from public.library l join public.anime a on a.id=l.anime_id where l.user_id=auth.uid() group by 1) s)) $$;
revoke all on function public.personal_statistics() from public,anon;
grant execute on function public.personal_statistics() to authenticated;
create function public.import_library(payload jsonb,merge_mode text) returns int language plpgsql security invoker set search_path='' as $$
declare item jsonb; total int; affected int; imported int:=0; begin
 if auth.uid() is null or merge_mode not in ('skip','replace') or jsonb_typeof(payload)<>'array' or jsonb_array_length(payload)>2000 or octet_length(payload::text)>2000000 then raise exception 'Invalid import';end if;
 for item in select value from jsonb_array_elements(payload) loop
  select episodes into total from public.anime where id=(item->>'anime_id')::bigint and moderation='published';
  if not found or (total is not null and (item->>'progress')::int>total) then continue; end if;
  insert into public.library(user_id,anime_id,status,progress,score,favorite,priority,notes,tags,rewatches,started_on,completed_on)
  select auth.uid(),r.anime_id,r.status,r.progress,r.score,r.favorite,r.priority,r.notes,r.tags,r.rewatches,r.started_on,r.completed_on from jsonb_populate_record(null::public.library,item) r
  on conflict(user_id,anime_id) do update set status=excluded.status,progress=excluded.progress,score=excluded.score,favorite=excluded.favorite,priority=excluded.priority,notes=excluded.notes,tags=excluded.tags,rewatches=excluded.rewatches,started_on=excluded.started_on,completed_on=excluded.completed_on where merge_mode='replace';
  get diagnostics affected=row_count;imported=imported+affected;
 end loop;
 return imported;
end $$;
revoke all on function public.import_library(jsonb,text) from public,anon;
grant execute on function public.import_library(jsonb,text) to authenticated;
create function public.pick_backlog() returns bigint language sql volatile security invoker set search_path='' as $$ select l.anime_id from public.library l join public.anime a on a.id=l.anime_id where l.user_id=auth.uid() and l.status='planned' and a.moderation='published' order by random() limit 1 $$;
revoke all on function public.pick_backlog() from public,anon;
grant execute on function public.pick_backlog() to authenticated;
